/// <summary>
/// CB 797 send PE pricing The service class for update sales order pricing from PE
/// </summary>
class METSendPEPricingEngine extends SysOperationServiceBase
{

    RecordInsertList      salesLinePriceComList = new RecordInsertList(tableNum(METSalesLinePriceComponent));
    RecordInsertList      insertCompDetailList = new RecordInsertList(tableNum(METSalesLinePriceComponentDetail));
    RecordInsertList      insertMarkupList = new RecordInsertList(tableNum(MarkupTrans));

    #define.CAMPBELLSPOS('CAMPBELLS POS')


}

Method.Source:
/// <summary>
/// PE Pricing update for salesorder
/// </summary>
/// <param name="_sendPEPricingRequest">
/// The contract instance
/// </param>
/// <returns>
/// The response <c>sendPEPricingRequest</c>
/// </returns>
public void sendPEPricingMessage(METSendPEPricingRequest _sendPEPricingRequest)
{
    METProcessingStatus result;
    Description255      message = "@MET:NoRecordsUpdated"; //default message

    this.processPESalesPricingUpdate(_sendPEPricingRequest);

}

/// <summary>
/// Process the PE Pricing for sales lines
/// </summary>
/// <param name="_sendPEPricingRequest">List of contracts</param>
/// <returns>Container of Results</returns>
public void processPESalesPricingUpdate(METSendPEPricingRequest _sendPEPricingRequest)
{
    METProcessingStatus result;
    Description255      message = "@MET:NoRecordsUpdated";
    container           resultCon;
    boolean             enableStagedCommit = SalesParameters::find().METEnableStagedCommitForPEPricingUpdate;

    if(!enableStagedCommit)
        ttsbegin;

    resultCon = this.sendPEHeaderPricing(_sendPEPricingRequest.parmSendPricingHeaderContract(), _sendPEPricingRequest);
    result = conPeek(resultCon, 1);
    message = conPeek(resultCon, 2);

    SalesId salesId = _sendPEPricingRequest.parmSendPricingHeaderContract().parmSalesId();
    // Throw the error if any node is fail and catupre in MES message log to fail
    if (result == METProcessingStatus::Error)
    {
        throw Error (message);
    }

    if(!enableStagedCommit)
        ttscommit;        
}

/// <summary>
/// PE sales order header details
/// </summary>
/// <param name = "_metSendPricingHeader">Contract class reference</param>
/// <param name="_sendPEPricingRequest">List of contracts</param>
/// <returns>Container</returns>
public container sendPEHeaderPricing(METSendPricingHeaderContract _metSendPricingHeader,
                                        METSendPEPricingRequest _sendPEPricingRequest)
{
    SalesTable                              salesTable;
    METProcessingStatus                     result;
    Description255                          messageLoc;
    SalesId                                 salesId;
    METExternalOrderNumber                  externalPEorderId;
    List                                    lines;
    ListEnumerator                          lineEnumerator;
    container                               resultCon;
    METSalesTable                           metSalesTable;

    salesId = _metSendPricingHeader.parmSalesId();
    externalPEorderId = _metSendPricingHeader.parmExternalOrderId();

    select firstonly salesTable where salesTable.SalesId == salesId;
    METSalesOrderTypes metSalesOrderTypes = METSalesOrderTypes::find(salesTable.METSalesOrderType);

    // Verify sales order is valid or not if no return.
    if (salesTable.SalesId == '')
    {
        throw error ("@MET:METOrderNotFound");
    }

    // Update the PE External orderId as a refrence from upstream
    select firstonly metSalesTable
            where metSalesTable.SalesTable == salesTable.RecId;

    //Create update salesLine
    lines = _sendPEPricingRequest.parmsendPEPricingLineClassArray();

    // To check Sales order is not invoiced primary check ready to update the salesline or not
    if (lines &&  salesTable.checkUpdate(true))
    {
        METSendPricingLineContract              sendPricingLineContract;
        boolean                                 avoidNegativeQtySalesId = false;
        SalesLine                               saleslinePre;
        WMSLocationId                           firstLineWMSLocationId;

        select firstonly InventDimId from saleslinePre
            order by saleslinePre.LineNum asc
            where saleslinePre.SalesId == salesTable.SalesId;
        firstLineWMSLocationId = InventDim::find(saleslinePre.InventDimId).wMSLocationId;

        lineEnumerator = lines.getEnumerator();


        ttsbegin; //Stage#1
        if (metSalesTable.OrderProcessingStatus == METSalesOrderProcessingStatus::ReadyForPricing ||
                metSalesTable.OrderProcessingStatus == METSalesOrderProcessingStatus::RepriceRequired)
        {
            while (lineEnumerator.moveNext())
            {
                sendPricingLineContract = lineEnumerator.current();
                avoidNegativeQtySalesId = avoidNegativeQtySalesId || (sendPricingLineContract.parmSalesQty() < 0);

                // Kept the condition outside for better understanding/Redability
                if (sendPricingLineContract.parmInventTransId() == '' &&
                salesTable.SalesType == SalesType::ReturnItem &&
                metSalesOrderTypes.ExternalInvoiceNumber)
                {
                    continue;
                }
                resultCon = this.createUpdateSalesLine(_sendPEPricingRequest, sendPricingLineContract, salesTable, firstLineWMSLocationId);
                result = conPeek(resultCon, 1);
                messageLoc = conPeek(resultCon, 2);
                if (result == METProcessingStatus::Error)
                {
                    return [result, messageLoc];
                }
            }

            //Bulk insert records
            salesLinePriceComList.insertDatabase(); // Bulk insert priceComponent
            insertCompDetailList.insertDatabase(); // Bulk insert compDetailRecords
            insertMarkupList.insertDatabase(); // Bulk insert Markup records
        }
        ttscommit; //Stage#1

        ttsbegin; //Stage#2
        if (metSalesTable.RecId != 0)
        {              
            if (metSalesTable.OrderProcessingStatus == METSalesOrderProcessingStatus::RepriceRequired)
            {
                WMSPickingRoute  wmsPickingRoute;

                select firstonly wmsPickingRoute
                where wmsPickingRoute.transType == InventTransType::Sales &&
                      wmsPickingRoute.transRefId == salesTable.SalesId;

                METCustomerMDFCalculation_PickingRoute custMDFCalculation = new METCustomerMDFCalculation_PickingRoute();
                custMDFCalculation.parmWMSPickingRouteID(wmsPickingRoute.pickingRouteID);
                custMDFCalculation.process();
            }

            metSalesTable.selectForUpdate(true);
            metSalesTable.ExternalOrderNumber = externalPEorderId;

            // Added if condition to avoid any edge scenario wrong status update on different status
            if (metSalesTable.OrderProcessingStatus == METSalesOrderProcessingStatus::ReadyForPricing ||
                metSalesTable.OrderProcessingStatus == METSalesOrderProcessingStatus::RepriceRequired)
            {
                metSalesTable.OrderProcessingStatus =
                            metSalesTable.OrderProcessingStatus == METSalesOrderProcessingStatus::ReadyForPricing
                            ? METSalesOrderProcessingStatus::PricingCompleted
                            : METSalesOrderProcessingStatus::RepriceCompleted;
            }

            metSalesTable.InvoiceNumber = _metSendPricingHeader.parminvoiceNumber() != '' ? _metSendPricingHeader.parminvoiceNumber() : metSalesTable.InvoiceNumber;
            metSalesTable.InvoiceTotal = _metSendPricingHeader.parmInvoiceTotal();
            metSalesTable.update();
        }
        ttscommit; //Stage#2

        // Generate picking list if required
        if (!avoidNegativeQtySalesId) //  Avoid the picking list generation if the sales qty negative which is not expected but added this check to avoid any edge case scenario
        {  
            ttsbegin; //Stage#3
            this.generatePickingListAndRegister(salesTable);
            ttscommit; //Stage#3
        }

        // Cancell the salesline post picking list generation if the sales qty is negative which is not expected but added this check to avoid any edge case scenario
        if (metSalesOrderTypes && metSalesOrderTypes.ExternalInvoiceNumber 
            && salesTable.METAllowBackOrders == NoYes::No)
        {
            SalesLine salesLineLoc;

            ttsbegin; //Stage#4
            while select forupdate salesLineLoc
                where salesLineLoc.SalesId      == salesTable.SalesId 
                && salesTable.METSalesOrderType != #CAMPBELLSPOS
                && salesLineLoc.SalesStatus     != SalesStatus::Canceled
                && salesLineLoc.LineAmount      == 0
            {
                if (salesLineLoc.pickedInTotalInventUnit() == 0)
                {                        
                    salesLineLoc.metCancelSalesOrderLine();            
                } 
            }
            ttscommit; //Stage#4
        }

        result      = METProcessingStatus::Success;
        messageLoc  = "@MET:METPricingSucessfullyProcessed";

    }
    else
    {
        result      = METProcessingStatus::Error;
        messageLoc  = "@MET:METInvalidSalesLineRecord";
    }

    return [result, messageLoc];
}

/// <summary>
/// Update insert sales line records.
////</summary>
/// <param name = "_sendPEPricingRequest">Contract class reference</param>
/// <param name="_sendPEPricingLineClass">List of contracts</param>
/// <param name="_salesTable">SalesTable</param>
/// <returns>Container</returns>
public container createUpdateSalesLine(METSendPEPricingRequest _sendPEPricingRequest,
                                        METSendPricingLineContract _sendPEPricingLineClass,
                                        SalesTable _salesTable,
                                        WMSLocationId _firstLineWMSLocationId)
{
    List                             priceComponents, markupTransRecords;
    ListEnumerator                   priceComponentEnumerator, markupTransEnumerator;
    SalesLine                        salesLineBuf;
    InventDim                        inventDim;
    METSalesLine                     metSalesLineBuf;
    METPriceComponentContract 	     priceComponentContract;
    METSendPricingMarkupDetailContract  markupTransContract;
    METProcessingStatus              result;
    Description255                   message;
    METSendPricingHeaderContract     sendPEPricingHeaderClass = _sendPEPricingRequest.parmSendPricingHeaderContract();
    container                        resultCon;
    InventTransId                    preInventTransId;
    real                             actualWeight;
    #define.Bonus('Bonus')
    #OCCRetryCount

    salesLineBuf =  SalesLine::findInventTransId(_sendPEPricingLineClass.parmInventTransId(), true);

    if (salesLineBuf.RecId == 0)
    {
        salesLineBuf.clear();
        salesLineBuf.SalesId = sendPEPricingHeaderClass.parmSalesId();
        salesLineBuf.ItemId = _sendPEPricingLineClass.parmItemId();

        //Initializing the sales line from inventory
        salesLineBuf.initFromInventTable(InventTable::find(salesLineBuf.ItemId));

        //Setting and creating inventory dimensions
        inventdim.InventSiteId = _salesTable.InventSiteId;
        inventdim.InventLocationId = _salesTable.InventLocationId;
        inventdim.wmsLocationId = _firstLineWMSLocationId;
        inventdim.inventBatchId = METConstants::defaultval;

        salesLineBuf.InventDimId = InventdIm::findOrCreate(inventDim).inventDimId;
        salesLineBuf.SalesQty = _sendPEPricingLineClass.parmSalesQty();
        SalesUnit salesUnit = _sendPEPricingLineClass.parmSalesUnit();

        if (salesUnit)
        {
            salesLineBuf.SalesUnit = salesUnit;
        }
        else
        {
            // InventItemSalesSetup inventory dimensions only have Site. Warehouse is not used here.
            // Also delete the empty salesLine variable as only salesLineBuf is used here
            InventDim inventDimInventItemSalesSetup;
            inventDimInventItemSalesSetup.InventSiteId = _salesTable.InventSiteId;
            InventDimId inventItemSalesSetupInventDimId = InventdIm::findOrCreate(inventDimInventItemSalesSetup).inventDimId;
            salesLineBuf.SalesUnit = InventItemSalesSetup::find(salesLineBuf.ItemId, inventItemSalesSetupInventDimId).METSalesUnit;
        }
        salesLineBuf.QtyOrdered = salesLineBuf.calcQtyOrdered();
        //salesLineBuf.SalesDeliverNow = salesLineBuf.SalesQty;
        //salesLineBuf.setInventDeliverNow();
        salesLineBuf.RemainSalesPhysical = salesLineBuf.SalesQty;
        salesLineBuf.RemainInventPhysical = salesLineBuf.QtyOrdered;

        salesLineBuf.createLine(NoYes::Yes, // Validate
        NoYes::Yes, // initFromSalesTable
        NoYes::No, // initFromInventTable
        NoYes::Yes, // calcInventQty
        NoYes::Yes, // searchMarkup
        NoYes::Yes); //

        //Set the values as per message
        salesLineBuf.SalesPrice = _sendPEPricingLineClass.parmSalesPrice();

        salesLineBuf.LineDisc = _sendPEPricingLineClass.parmSalesLineDisc();

        // Bug 264186: CB797 - Pricing Message failing for Discount Bonus lines on SaleUnit

        salesLineBuf.LineAmount  = salesLineBuf.calcLineAmount();
        salesLineBuf.update();
    }
    else
    {
        //Set the values as per message
        if (salesLineBuf.SalesPrice != _sendPEPricingLineClass.parmSalesPrice())
        {
            salesLineBuf.SalesPrice = _sendPEPricingLineClass.parmSalesPrice();
        }
        // Bug 331584: - Optimization of Dual Write for sales lines
        if (salesLineBuf.SalesQty != _sendPEPricingLineClass.parmSalesQty())
        {
            salesLineBuf.SalesQty = _sendPEPricingLineClass.parmSalesQty();
        }

        if (salesLineBuf.LineDisc != _sendPEPricingLineClass.parmSalesLineDisc())
        {
            salesLineBuf.LineDisc = _sendPEPricingLineClass.parmSalesLineDisc();
        }
        //salesLineBuf.SalesUnit = _sendPEPricingLineClass.parmSalesUnit() != '' ? _sendPEPricingLineClass.parmSalesUnit() : InventItemSalesSetup::find(salesLine.ItemId, salesLine.InventDimId).METSalesUnit;
        if (salesLineBuf.LineAmount != salesLineBuf.calcLineAmount())
        {
            salesLineBuf.LineAmount = salesLineBuf.calcLineAmount();
        }

        salesLineBuf.update();
    }



    // Fetch METSalesLine once for weight and bonus type updates
    metSalesLineBuf = METSalesLine::find(salesLineBuf.RecId, true);
    boolean metSalesLineChanged = false;

    if (metSalesLineBuf.RecId != 0)
    {
        actualWeight = _sendPEPricingLineClass.parmActualWeight();
        if (actualWeight != 0)
        {
            metSalesLineBuf.AISWeight = actualWeight;
            metSalesLineChanged = true;
        }
    }

    // price component insert or update
    priceComponents = _sendPEPricingLineClass.parmsendPEPriceComponetClassArray();

    if (priceComponents)
    {
        priceComponentEnumerator = priceComponents.getEnumerator();
        while (priceComponentEnumerator.moveNext())
        {
            priceComponentContract = priceComponentEnumerator.current();
            resultCon = this.createUpdatePriceComponent(priceComponentContract, salesLineBuf);
            result = conPeek(resultCon, 1);
            message = conPeek(resultCon, 2);

            if (result == METProcessingStatus::Error)
            {
                return [result, message];
            }

            if (priceComponentContract.parmComponent() == #Bonus && metSalesLineBuf.RecId != 0)
            {
                metSalesLineBuf.BonusType = priceComponentContract.parmPriceCodeRef() != '' ? METBonusType::DiscountBonus : METBonusType::Bonus;
                metSalesLineChanged = true;
            }
        }
    }

    if (metSalesLineChanged)
    {
        metSalesLineBuf.update();
    }

    // Markuptrans record update insert based on salesline level
    markupTransRecords = _sendPEPricingLineClass.parmsendPEMarkupTransClassArray();

    if (markupTransRecords)
    {
        markupTransEnumerator = markupTransRecords.getEnumerator();
        while (markupTransEnumerator.moveNext())
        {
            markupTransContract = markupTransEnumerator.current();
            resultCon = this.createUpdateMarkupTrans(markupTransContract, salesLineBuf, _salesTable);
            result = conPeek(resultCon, 1);
            message = conPeek(resultCon, 2);
            if (result == METProcessingStatus::Error)
            {
                return [result, message];
            }
        }
    }

    return [result, message];

}

/// <summary>
/// Update insert price component
/// </summary>
/// <param name="_priceComponentContract">PE pricingRquest</param>
/// <param name="_salesline">salesline</param>
/// <returns>Container</returns>
public container createUpdatePriceComponent(METPriceComponentContract _priceComponentContract, SalesLine _salesline)
{
    METSalesLinePriceComponent      salesLinePriceComponent, salesLinePriceComInsert;
    List                            salesLinePriceComDetail;
    ListEnumerator                  priceCompDetailEnumerator;
    METPriceComponentDetailContract priceCompDetailContract;
    METProcessingStatus              result;
    Description255                   message;
    container                        resultCon;

    #OCCRetryCount

    salesLinePriceComponent = METSalesLinePriceComponent::find(_salesline.InventTransId,
                                                              _priceComponentContract.parmComponent(),
                                                              _priceComponentContract.parmPriceCodeRef(), true);

    if (salesLinePriceComponent.RecId == 0)
    {
        salesLinePriceComInsert.clear();
        salesLinePriceComInsert.InventTransId = _salesline.InventTransId;
        salesLinePriceComInsert.Component     = _priceComponentContract.parmComponent();
        salesLinePriceComInsert.PriceCodeRef  = _priceComponentContract.parmPriceCodeRef();
        salesLinePriceComInsert.Value         = _priceComponentContract.parmAmountValue();
        salesLinePriceComInsert.FeeCode       = _priceComponentContract.parmfeeCode();
        // Validate the write operation before inserting
        message = salesLinePriceComInsert.validateValue();

        if (message == '')
        {
            salesLinePriceComList.add(salesLinePriceComInsert);
        }

    }
    else
    {
        salesLinePriceComponent.PriceCodeRef  = _priceComponentContract.parmPriceCodeRef();
        salesLinePriceComponent.Value         = _priceComponentContract.parmAmountValue();
        // Validate the write operation before updating
        message = salesLinePriceComponent.validateValue();

        if (message == '')
        {
            salesLinePriceComponent.update();
        }
    }

    // Pass the error message to AIS
    if (message != '')
    {
        throw error (message);
    }

    // price component insert or update
    salesLinePriceComDetail = _priceComponentContract.parmsendPEPriceComponetDetailClassArray();

    if (salesLinePriceComDetail)
    {
        priceCompDetailEnumerator = salesLinePriceComDetail.getEnumerator();

        while (priceCompDetailEnumerator.moveNext())
        {
            priceCompDetailContract = priceCompDetailEnumerator.current();
            resultCon = this.createPriceComponentDetail(priceCompDetailContract, _salesline.InventTransId, _priceComponentContract.parmPriceCodeRef());
            result = conPeek(resultCon, 1);
            message = conPeek(resultCon, 2);
        }
    }

    return [result, message];
}

/// <summary>
/// Insert price component details
/// </summary>
/// <param name="_priceComponentDetailContract">PE pricing Detail Contract</param>
/// <param name="_salesLineInventTransId">PE pricing Detail Contract</param>
/// <param name="_priceCodeRef">PE pricing Detail Contract</param>
/// <returns>Container</returns>
public container createPriceComponentDetail(METPriceComponentDetailContract _priceComponentDetailContract,
                                            InventTransId                   _salesLineInventTransId,
                                            METPriceCodeRef                 _priceCodeRef)
{

    METSalesLinePriceComponentDetail    salesLinePriceComDetail, salesLinePriceCompDetailInsert;
    METProcessingStatus                 result;
    Description255                      message;
    #OCCRetryCount

    salesLinePriceCompDetailInsert.clear();
    salesLinePriceCompDetailInsert.InventTransId   = _salesLineInventTransId;
    salesLinePriceCompDetailInsert.Component       = _priceComponentDetailContract.parmComponent();
    salesLinePriceCompDetailInsert.Code            = _priceComponentDetailContract.parmCodeId();
    salesLinePriceCompDetailInsert.Reference       = _priceComponentDetailContract.parmReference();
    salesLinePriceCompDetailInsert.ToDate          = _priceComponentDetailContract.parmToDate();
    salesLinePriceCompDetailInsert.FromDate        = _priceComponentDetailContract.parmFromDate();
    salesLinePriceCompDetailInsert.Value           = _priceComponentDetailContract.parmCustomerAllowance();
    salesLinePriceCompDetailInsert.VendorValue     = _priceComponentDetailContract.parmVendorAllowance();
    salesLinePriceCompDetailInsert.priceCodeRef    = _priceCodeRef;
    // Validate the write operation before inserting
    message = salesLinePriceCompDetailInsert.validateValue();

    if (message == '')
    {
        insertCompDetailList.add(salesLinePriceCompDetailInsert);
    }

    // Pass the error message to AIS
    if (message != '')
    {
        throw error (message);
    }

    return [result, message];
}

/// <summary>
/// Update insert markupTrans value
/// </summary>
/// <param name="_markupTransDetail">PE markupTrans records</param>
/// <param name="_salesline">InventTransId</param>
/// <param name="_salesTable">salesTable</param>
/// <returns>Container</returns>
public container createUpdateMarkupTrans(METSendPricingMarkupDetailContract _markupTransDetail,Salesline _salesline, SalesTable _salesTable)
{
    METProcessingStatus     result;
    Description255          message;
    MarkupTrans             markupTrans;
    InventTransId           inventTransId;
    InventTableModule       inventModule;
    MarkupTable             markupTable;
    #define.AUD('AUD')
    #define.GST('GST')
    #define.WEG('WEG')
    #OCCRetryCount


    select firstonly forupdate markupTrans
                where markupTrans.TransRecId == _salesline.RecId &&
                        markupTrans.LineNum == _markupTransDetail.parmLineNum() &&
                        markupTrans.TransTableId == tableNum(SalesLine);

    select firstonly TaxItemGroupId  from inventModule
        where inventModule.ItemId == _salesline.ItemId &&
        inventModule.ModuleType == ModuleInventPurchSales::Sales;



    // Write function did not work out used insert update
    if (markupTrans.RecId !=0 )
    {
        markupTrans.MarkupCode       = _markupTransDetail.parmMarkupCode();
        markupTrans.MarkupCategory   = MarkupCategory::Pcs;
        markupTrans.METChargesMethod = _markupTransDetail.parmMETChargesMethod();
        markupTrans.Value            = _markupTransDetail.parmChargeValue();
        markupTrans.Txt              = MarkupTable::find(MarkupModuleType::Cust,  markupTrans.MarkupCode).Txt;
        markupTrans.CurrencyCode     = #AUD;
        markupTrans.TaxGroup         = #GST;
        markupTrans.TaxItemGroup     = inventModule.TaxItemGroupId != #WEG ? inventModule.TaxItemGroupId : #GST;
        if (markupTrans.validateWrite())
        {
            markupTrans.update();
        }
        else
        {
            throw error("@SYS104318");
        }

    }
    else
    {
        markUpTrans.initFromSalesTable(_salesTable);
        markupTrans.TransRecId       = _salesline.RecId;
        markupTrans.TransTableId     = tableNum(SalesLine);
        markupTrans.LineNum          = _markupTransDetail.parmLineNum();
        markupTrans.MarkupCode       = _markupTransDetail.parmMarkupCode();
        markupTrans.MarkupCategory   = MarkupCategory::Pcs;
        markupTrans.METChargesMethod = _markupTransDetail.parmMETChargesMethod();
        markupTrans.Value            = _markupTransDetail.parmChargeValue();
        markupTrans.Txt              = MarkupTable::find(MarkupModuleType::Cust,  markupTrans.MarkupCode).Txt;
        markupTrans.CurrencyCode     = #AUD;
        markupTrans.TaxGroup         = #GST;
        markupTrans.TaxItemGroup     = inventModule.TaxItemGroupId != #WEG ? inventModule.TaxItemGroupId : #GST;
        markupTrans.validateWrite();
        if (markupTrans.validateWrite())
        {
            insertMarkupList.add(markupTrans);
        }
        else
        {
            throw error("@SYS104318");
        }

    }

    return [result, message];
}

/// <summary>
/// Capture the Error Log message
/// </summary>
/// <returns>errorLog</returns>
private str getErrorStr()
{
    SysInfologEnumerator enumerator;
    SysInfologMessageStruct msgStruct;
    Exception exception;
    str error;
    enumerator = SysInfologEnumerator::newData(infolog.cut());
    while (enumerator.moveNext())
    {
        msgStruct = new SysInfologMessageStruct(enumerator.currentMessage());
        exception = enumerator.currentException();
        error = strfmt("%1", error, msgStruct.message());
    }
    return error;
}

/// <summary>
/// Generate picking list and register it for the sales order if required
/// </summary>
/// <param name = "_salesTable">The sales table for which to generate and register the picking list</param>
private void generatePickingListAndRegister(SalesTable _salesTable)
{
    WMSOrderTrans           wmsOrderTrans;
    WMSPickingRoute         wmsPickingRoute;
    SalesFormLetter         salesFormLetter;
    SalesParmTable          salesParmTable;
    SalesParmLine           salesParmLine;
    SalesLine               salesLineLoc;
    METSalesLine            metSalesLine;
    boolean                 pickingExists = false;
    METSalesOrderTypes      metSalesOrderTypes = METSalesOrderTypes::find(_salesTable.METSalesOrderType);
    Map                     qtyMap = new Map(Types::String, Types::Container);

    if (!_salesTable || !_salesTable.SalesId || !metSalesOrderTypes.ExternalInvoiceNumber)
    {
        return;
    }

    // Check if picking route already exists
    select firstonly wmsPickingRoute
            where wmsPickingRoute.transType  == InventTransType::Sales
            && wmsPickingRoute.transRefId == _salesTable.SalesId;

    if (wmsPickingRoute.RecId)
    {
        pickingExists = true;
    }

    // Create Picking List if not exists
    if (!pickingExists)
    {
        salesFormLetter = SalesFormLetter::construct(DocumentStatus::PickingList);
        Query query = new Query(QueryStr(SalesUpdate));
        QueryBuildDataSource qbdsSalesTable = query.dataSourceTable(tableNum(SalesTable));
        qbdsSalesTable.addRange(fieldNum(SalesTable, SalesId)).value(queryValue(_salesTable.SalesId));

        //CB797 - PB187: Cancel unpicked CCC SO Lines - start.
        QueryBuildDataSource qbdsSalesLine = query.dataSourceTable(tableNum(SalesLine));
        qbdsSalesLine.addRange(fieldNum(SalesLine, SalesQty)).value(queryValue('>0')); 

        if (_salesTable.METSalesOrderType != #CAMPBELLSPOS)
        {
            qbdsSalesLine.addRange(fieldNum(SalesLine, LineAmount)).value(queryValue('>0'));
        }
        //CB797 - PB187: Cancel unpicked CCC SO Lines - end.

        QueryRun queryRun = new sysQueryRun(query);
        salesFormLetter.chooseLinesQuery(queryRun);
        salesFormLetter.salesTable(_salestable);
        salesFormLetter.initParmSalesTable(salesFormLetter.salesTable());
        salesFormLetter.transDate(DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));
        salesFormLetter.specQty(SalesUpdate::All);
        salesFormLetter.printFormLetter(false);
        salesFormLetter.createParmUpdateFromParmUpdateRecord(SalesFormletterParmData::initSalesParmUpdateFormletter(salesFormLetter.documentStatus(), salesFormLetter.pack()));

        salesFormLetter.salesParmUpdate().ReduceOnHand  = NoYes::No;
        salesFormLetter.salesParmUpdate().Reserve       = NoYes::No;

        salesFormLetter.initParameters(salesFormLetter.salesParmUpdate(), Printout::Current);
        salesFormLetter.initLinesQuery();

        while select forupdate salesParmLine
                where salesParmLine.ParmId == salesFormLetter.parmId()
        {
            salesLineLoc = salesParmLine.salesLine();

            boolean isCWItem = PdsGlobal::pdsIsCWItem(salesLineLoc.ItemId);

            if (isCWItem)
            {
                metSalesLine = METSalesLine::find(salesLineLoc.RecId);
                salesParmLine.PdsCWDeliverNow = salesLineLoc.SalesQty;
                salesParmLine.DeliverNow = metSalesLine.AISWeight;
                qtyMap.insert(salesLineLoc.InventTransId, [1, salesLineLoc.SalesQty, metSalesLine.AISWeight]);
            }
            else
            {
                salesParmLine.DeliverNow = salesLineLoc.SalesQty;
            }

            salesParmLine.setQty(DocumentStatus::PickingList, false);
            salesParmLine.update();

            if (!isCWItem)
            {
                qtyMap.insert(salesLineLoc.InventTransId, [0, salesParmLine.InventNow, 0.0]);//SalesQty in inventory units
            }
        }

        salesFormLetter.run();
    }

    // Re-read picking route
    select firstonly wmsPickingRoute
            where wmsPickingRoute.transType  == InventTransType::Sales
            && wmsPickingRoute.transRefId == _salesTable.SalesId;

    if (wmsPickingRoute.RecId)
    {
        ttsbegin;
        wmsPickingRoute.selectForUpdate(true);
        wmsPickingRoute.METExternalInvoicedSO = NoYes::Yes;
        wmsPickingRoute.update();

        while select forupdate wmsOrderTrans
            where wmsOrderTrans.routeId == wmsPickingRoute.pickingRouteID
        {
            container qtyContainer = qtyMap.lookup(wmsOrderTrans.inventTransId);
            if (qtyContainer)
            {
                boolean isCWItem = conPeek(qtyContainer, 1);
                InventQty salesQty = conPeek(qtyContainer, 2);
                InventQty aisWeight = conPeek(qtyContainer, 3);

                wmsOrderTrans.qty = isCWItem ? aisWeight : salesQty;

                if (isCWItem)
                {
                    wmsOrderTrans.PdsCWQty = salesQty;
                }

                wmsOrderTrans.wmsOrderTransType().updateQty();
                wmsOrderTrans.METPickedQtyProcessed = NoYes::No;
                wmsOrderTrans.METPickedQtyUpdated = NoYes::Yes;
                wmsOrderTrans.update();
            }
        }
        ttscommit;
    }

}

/// <summary>
/// Reserves the sales order line with the quantity picked.
/// </summary>
/// <param name = "_salesLine">Sales line</param>
/// <param name = "_qtyPicked">Quantity to reserve</param>
public void reserveSOLineQty(SalesLine _salesLine, InventQty _qtyPicked)
{
    InventMovement movement = InventMovement::construct(_salesLine);
    InventUpd_Reservation reservation = InventUpd_Reservation::newMovement(movement, -_qtyPicked, true);
    reservation.updateNow();
}

/// <summary>
/// Construct method to create new instance
/// </summary>
/// <returns>METSendPEPricingEngine</returns>
Public static METSendPEPricingEngine construct()
{
    return new METSendPEPricingEngine();
}
